<?php declare(strict_types="1"); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free PDF Blank Page Checker','description'=>'Inspect a PDF for pages that appear to contain no text objects.','url'=>'https://smarttoolz.in/tools/pdf-blank-page-checker/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>PDF Blank Page Checker</h1><p>Scan PDF page objects for likely blank pages.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="f" type="file" accept="application/pdf"><button id="go" class="tool-btn">Check Blank Pages</button><pre id="o"></pre></div></section></main><script>go.onclick=async()=>{let f=document.getElementById('f').files[0];if(!f)return;let s=new TextDecoder('latin1').decode(new Uint8Array(await f.arrayBuffer()));let pages=(s.match(/\/Type\s*\/Page\b/g)||[]).length,streams=(s.match(/\/Contents\b/g)||[]).length;o.textContent=`Pages detected: ${pages}\nContent references: ${streams}\n\nThis is a basic structural check; scanned/image-only pages may not be detected as blank.`}</script><?php smarttoolz_tool_page_end(); ?>